import java.util.ArrayList;
import java.util.List;

/**
 * Utility that wraps a sentence and can truncate it without breaking words.
 */
public final class SentenceTruncator {
    private final String original;

    public SentenceTruncator(String text) {
        this.original = text == null ? "" : text.trim();
    }

    /**
     * @param maxLen maximum allowed length (including suffix)
     * @param suffix string appended when truncation occurs
     * @return truncated sentence
     * @throws IllegalArgumentException if arguments are invalid
     */
    public String truncate(int maxLen, String suffix) {
        if (maxLen < 1) throw new IllegalArgumentException("maxLen must be >= 1");
        if (suffix == null) suffix = "...";
        if (suffix.length() > maxLen)
            throw new IllegalArgumentException("suffix longer than maxLen");

        if (original.length() <= maxLen) return original;

        int room = maxLen - suffix.length();
        String[] words = original.split("\\s+");

        List<String> kept = new ArrayList<>();
        int cur = 0;

        for (String w : words) {
            int extra = w.length() + (kept.isEmpty() ? 0 : 1);
            if (cur + extra > room) break;
            kept.add(w);
            cur += extra;
        }

        if (kept.isEmpty()) return suffix;
        return String.join(" ", kept) + suffix;
    }

    /** Overload that uses the default "..." suffix */
    public String truncate(int maxLen) {
        return truncate(maxLen, "...");
    }

    @Override
    public String toString() {
        return original;
    }
}
