      'fallback'
    );
    expect(result).toBe(
      '⚠️ Low stock: Gadget – only 2 units left. Please reorder soon.'
    );
  });

  it('uses fallback when name is missing', () => {
    const result = formatLowStockAlert({ remainingUnits: 5 }, 'fallback text');
    expect(result).toBe('fallback text');
  });

  it('handles singular unit correctly', () => {
    const result = formatLowStockAlert(
      { name: 'Widget', remainingUnits: 1 },
      'fallback'
    );
