Below is a **stand‑alone utility function** that you can drop into a server‑side codebase (Node.js / Express, Fastify, AWS Lambda etc.) or into any JavaScript/TypeScript project.  

It:

1. **Inspects the incoming payload** (plain object, `req.body`, etc.).
2. **Ensures the three required properties** – `id`, `email`, **and** `role` – are present *and* non‑empty.
3. Returns a **consistent error object** that names every missing field (or an empty array if everything is fine) so the caller can decide how to respond (HTTP 400, log, etc.).

```ts
/**
 * Validate that a payload contains the required fields: `id`, `email`, and `role`.
 *
 * @param payload   The incoming object to validate (e.g. req.body)
 * @returns         An object describing the validation result.
 *
 *   {
 *     isValid: boolean          // true if all required fields exist
 *     missing: string[]         // array of missing field names (empty when valid)
 *     message?: string          // human‑readable error message (only when invalid)
 *   }
 */
export function validateRequiredFields(payload: unknown): {
  isValid: boolean
  missing: string[]
  message?: string
} {
  // 1️⃣ Guard against non‑objects (e.g. undefined, null, primitive values)
  if (payload === null || typeof payload !== 'object') {
    return {
      isValid: false,
      missing: ['id', 'email', 'role'],
      message: 'Payload must be a JSON object containing id, email and role.',
    };
  }

  // 2️⃣ Cast to a loose "record" type so we can index it safely.
  const record = payload as Record<string, unknown>;

  // 3️⃣ List the fields we care about.
  const required = ['id', 'email', 'role'] as const;

  // 4️⃣ Collect the ones that are absent or “empty” (empty string / null / undefined).
  const missing = required.filter((key) => {
    const value = record[key];
    // Treat undefined, null, empty string, and empty array/object as missing.
    if (value === undefined || value === null) return true;
    if (typeof value === 'string' && value.trim() === '') return true;
    if (Array.isArray(value) && value.length === 0) return true;
    if (typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length === 0) return true;
    return false;
  });

  // 5️⃣ Build the output.
  if (missing.length === 0) {
    return { isValid: true, missing: [] };
  }

  const message = `Missing required field${missing.length > 1 ? 's' : ''}: ${missing.join(', ')}`;
  return { isValid: false, missing, message };
}
```

---

## How to Use It

### In an Express route

```ts
import express from 'express';
import { validateRequiredFields } from './validation';

const app = express();
app.use(express.json());

app.post('/users', (req, res) => {
  const validation = validateRequiredFields(req.body);

  if (!validation.isValid) {
    // HTTP 400 Bad Request with a clear error message
    return res.status(400).json({
      error: validation.message,
      missing: validation.missing,
    });
  }

  // All required fields are present → proceed with your business logic
  const { id, email, role } = req.body;
  // ... create the user, store in DB, etc.
  res.status(201).json({ id, email, role });
});
```

### In an AWS Lambda (Node.js 18+)

```ts
import { APIGatewayProxyEvent, APIGatewayProxyResult } from 'aws-lambda';
import { validateRequiredFields } from './validation';

export const handler = async (event: APIGatewayProxyEvent): Promise<APIGatewayProxyResult> => {
  const body = event.body ? JSON.parse(event.body) : {};

  const validation = validateRequiredFields(body);
  if (!validation.isValid) {
    return {
      statusCode: 400,
      body: JSON.stringify({
        error: validation.message,
        missing: validation.missing,
      }),
    };
  }

  // Continue with main logic …
  return {
    statusCode: 200,
    body: JSON.stringify({ message: 'All required fields present.' }),
  };
};
```

