## 7️⃣ Quick‑Start Boilerplate (Node‑JS + SQLite)

If you’d rather copy‑paste a **ready‑to‑run** mini‑project, here’s a tiny Node script that uses **sqlite3** for persistence.

```js
// job-runner.js -------------------------------------------------
import sqlite3 from 'sqlite3'
import { open } from 'sqlite'

async function initDB() {
  const db = await open({
    filename: ':memory:',
    driver: sqlite3.Database
  })
  await db.exec(`
    CREATE TABLE jobs (
      id TEXT PRIMARY KEY,
      name TEXT,
      state TEXT,
      attempt INTEGER,
      maxAttempts INTEGER,
      payload TEXT,
      error TEXT,
      createdAt TEXT,
      updatedAt TEXT
    )
  `)
  return db
}

// ---------- Helper ----------
function status(job) {
  return `Job "${job.name}" – Attempt ${job.attempt} – ${job.state}`
}

// ---------- Transitions ----------
async function start(db, id) {
  const job = await db.get('SELECT * FROM jobs WHERE id = ? AND state = "PENDING"', id)
  if (!job) throw new Error('Job not pending')
  await db.run(`
    UPDATE jobs SET state = "RUNNING", updatedAt = datetime('now')
    WHERE id = ?
  `, id)
  job.state = 'RUNNING'
  console.log(status(job))
}

async function succeed(db, id) {
  const job = await db.get('SELECT * FROM jobs WHERE id = ? AND state = "RUNNING"', id)
  if (!job) throw new Error('Job not running')
  await db.run(`
    UPDATE jobs SET state = "DONE", updatedAt = datetime('now')
    WHERE id = ?
  `, id)
  job.state = 'DONE'
  console.log(status(job))
}

async function fail(db, id, errMsg) {
  const job = await db.get('SELECT * FROM jobs WHERE id = ? AND state = "RUNNING"', id)
  if (!job) throw new Error('Job not running')
  const nextState = (job.maxAttempts && job.attempt >= job.maxAttempts) ? 'DONE' : 'FAILED'
  await db.run(`
    UPDATE jobs
       SET state = ?, error = ?, updatedAt = datetime('now')
     WHERE id = ?
  `, nextState, errMsg, id)
  job.state = nextState
  job.error = errMsg
  console.log(status(job))
}

async function retry(db, id) {
  const job = await db.get('SELECT * FROM jobs WHERE id = ? AND state = "FAILED"', id)
  if (!job) throw new Error('Job not failed')
  const nextAttempt = job.attempt + 1
  const nextState = (job.maxAttempts && nextAttempt > job.maxAttempts) ? 'DONE' : 'PENDING'
  await db.run(`
    UPDATE jobs
       SET state = ?, attempt = ?, error = NULL, updatedAt = datetime('now')
     WHERE id = ?
  `, nextState, nextAttempt, id)
  job.state = nextState
  job.attempt = nextAttempt
  console.log(status(job))
}

// ---------- Demo ----------
(async () => {
  const db = await initDB()
  // Insert a sample job
  await db.run(`
    INSERT INTO jobs (id, name, state, attempt, maxAttempts, payload, createdAt, updatedAt)
    VALUES ('1', 'ImageResize', 'PENDING', 1, 3, '{}', datetime('now'), datetime('now'))
  `)

  // Run the lifecycle
  await start(db, '1')
  await fail(db, '1', 'Network timeout')
  await retry(db, '1')
  await start(db, '1')
  await succeed(db, '1')
  // => console prints each status message
})()
```

