#include <iostream>
#include <string>
#include <iomanip>   // for std::setw

void printReportHeader(const std::string& schoolName, std::size_t width = 40) {
    if (schoolName.length() > width) {
        throw std::runtime_error("School name longer than the specified width");
    }

    std::string line(width, '=');

    // std::setw only affects the next insertion, so we use it twice:
    std::cout << line << '\n';
    std::cout << std::setw(static_cast<int>(width))
              << std::right << schoolName << '\n';
    std::cout << line << '\n';
}

