## Bash (for quick command‑line scripts)

```bash
#!/usr/bin/env bash
# Usage: ./header.sh "Springfield Elementary"

school_name="$1"
width=40

# If the name is longer than the width, truncate it
if (( ${#school_name} > width )); then
    school_name="${school_name:0:width}"
fi

line=$(printf '=%.0s' $(seq 1 $width))
printf "%s\n" "$line"

# Center the name using printf's width specifier
printf "%*s\n" $(( (width + ${#school_name}) / 2 )) "$school_name"

printf "%s\n" "$line"
```

